        .district-purnia { border-left-color: #667eea; }
        .district-nalanda { border-left-color: #764ba2; }
        .district-name {
            font-size: 2.5em;
            font-weight: bold;
            margin-bottom: 20px;
            text-align: center;
        }
        .district-purnia .district-name { color: #667eea; }
        .district-nalanda .district-name { color: #764ba2; }
        .stat-row {
            display: flex;
            justify-content: space-between;
            padding: 12px 0;
            border-bottom: 1px solid #ddd;
        }
