            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 20px;
            background: white;
            border-radius: 10px;
            margin: 10px 0;
            box-shadow: 0 3px 10px rgba(0,0,0,0.1);
        }
        .gap-name {
            font-size: 1.2em;
            font-weight: 600;
        }
        .gap-arrow {
            font-size: 2em;
            margin: 0 15px;
        }
        .gap-value {
            font-size: 2em;
            font-weight: bold;
            padding: 10px 25px;
            border-radius: 10px;
        }
        .gap-puroia-lower { background: #ffebee; color: #c62828; }
        .gap-nalanda-higher { background: #e8f5e9; color: #2e7d32; }
        .supports {
            text-align: center;
            margin-top: 30px;
            padding: 20px;
            background: #e3f2fd;
            border-radius: 10px;
        }
        .formula {
            font-family: 'Courier New', monospace;
            background: #f5f5f5;
