        .progress-bar {
            background: #ddd;
            border-radius: 10px;
            height: 25px;
            overflow: hidden;
            margin-top: 5px;
        }
        .progress-fill {
            height: 100%;
            border-radius: 10px;
            text-align: center;
            line-height: 25px;
            font-weight: bold;
            color: white;
        }
        .fill-completion { background: linear-gradient(90deg, #56ab2f, #a8e063); }
        .fill-employment { background: linear-gradient(90deg, #f59e0b, #fbbf24); }
    </style>
</head>
<body>
    <div class="container">
        <h1>📊 District Comparison Report - Year 2023</h1>
        <p class="subtitle">Purnia vs Nalanda - Women Training & Employment Analysis</p>

        <!-- District Cards Side by Side -->
        <div class="district-comparison">
            <!-- Purnia -->
            <div class="district-card district-purnia">
                <div class="district-name">📍 Purnia</div>
                <div class="stat-row">
                    <span class="stat-label">Total Women Trained</span>
                    <span class="stat-value">2,500</span>
                </div>
                <div class="stat-row">
                    <span class="stat-label">Completed Training</span>
                    <span class="stat-value">1,950</span>
                </div>
                <div class="stat-row">
                    <span class="stat-label">Employed (6 Months)</span>
                    <span class="stat-value">1,275</span>
                </div>

                <!-- Visual Progress Bars -->
                <div style="margin-top: 30px;">
                    <div class="stat-label">Completion Rate</div>
                    <div class="progress-bar">
                        <div class="progress-fill fill-completion" style="width: 78%;">78.0%</div>
                    </div>
                </div>
                <div style="margin-top: 15px;">
                    <div class="stat-label">Employment Rate (post-training)</div>
                    <div class="progress-bar">
                        <div class="progress-fill fill-employment" style="width: 65.4%;">65.4%</div>
                    </div>
                </div>
            </div>

            <!-- Nalanda -->
            <div class="district-card district-nalanda">
                <div class="district-name">📍 Nalanda</div>
                <div class="stat-row">
                    <span class="stat-label">Total Women Trained</span>
                    <span class="stat-value">1,950</span>
                </div>
                <div class="stat-row">
                    <span class="stat-label">Completed Training</span>
                    <span class="stat-value">1,425</span>
                </div>
                <div class="stat-row">
                    <span class="stat-label">Employed (6 Months)</span>
                    <span class="stat-value">897</span>
                </div>

                <!-- Visual Progress Bars -->
                <div style="margin-top: 30px;">
                    <div class="stat-label">Completion Rate</div>
                    <div class="progress-bar">
                        <div class="progress-fill fill-completion" style="width: 73.1%;">73.1%</div>
                    </div>
                </div>
                <div style="margin-top: 15px;">
                    <div class="stat-label">Employment Rate (post-training)</div>
                    <div class="progress-bar">
                        <div class="progress-fill fill-employment" style="width: 62.9%; background: linear-gradient(90deg, #f59e0b, #fbbf24);">62.9%</div>
                    </div>
                </div>
            </div>
        </div>

        <!-- Gap Analysis Section -->
        <div class="gap-section">
            <h2 class="gap-title">📈 Gap Analysis - Percentage Points</h2>

            <!-- Training Completion Gap -->
            <div class="gap-card">
                <div class="gap-name">Training Completion Rate</div>
                <div class="gap-arrow">➡️</div>
                <div class="gap-value gap-puroia-lower">
                    -4.9 percentage points
                </div>
            </div>

            <p style="text-align: center; color: #666; margin: 15px 0;">
                Purnia's completion rate is <strong>4.9 percentage points higher</strong> than Nalanda
            </p>

            <!-- Employment Gap -->
            <div class="gap-card">
                <div class="gap-name">Employment Rate (Post-Training)</div>
                <div class="gap-arrow">↓</div>
                <div class="gap-value gap-puroia-lower">
                    -2.5 percentage points
                </div>
            </div>

            <p style="text-align: center; color: #666; margin: 15px 0;">
                Purnia's employment rate is <strong>2.5 percentage points higher</strong> than Nalanda
            </p>

            <hr style="margin: 30px 0; border: none; border-top: 2px dashed #ddd;">

            <!-- Summary Cards -->
            <div class="gap-card">
                <div class="gap-name">📊 Overall Assessments</div>
                <div class="gap-arrow">✅</div>
                <div class="gap-value" style="background: #e8f5e9; color: #2e7d32;">
                    Purnia Leading
                </div>
            </div>
        </div>

        <!-- Detailed Comparison Table -->
        <div class="supports">
            <h3>📋 Detailed Comparison & Calculations</h3>
            <table>
                <thead>
                    <tr>
                        <th>Metric</th>
                        <th>Formula</th>
                        <th>Purnia (2023)</th>
                        <th>Nalanda (2023)</th>
                        <th>Gap</th>
                    </tr>
                </thead>
                <tbody>
                    <tr>
                        <td>Training Completion %</td>
                        <td class="formula">(Completed ÷ Trained) × 100</td>
                        <td><strong>78.0%</strong></td>
                        <td><strong>73.1%</strong></td>
                        <td class="gap-puroia-lower">+4.9</td>
                    </tr>
                    <tr>
                        <td>Employment Rate %</td>
                        <td class="formula">(Employed ÷ Completed) × 100</td>
                        <td><strong>65.4%</strong></td>
                        <td><strong>62.9%</strong></td>
                        <td class="gap-puroia-lower">+2.5</td>
                    </tr>
                </tbody>
            </table>
        </div>

        <footer>
            <p><strong>Formulas Used:</strong></p>
            <p>1. Completion Rate = (Women Who Completed ÷ Women Trained) × 100</p>
            <p>2. Employment Rate = (Women Employed 6mo Post-Training ÷ Women Who Completed) × 100</p>
            <p>Gap = Purnia Rate - Nalanda Rate (positive = Purnia leads)</p>
            <p>© 2023 District Training Monitoring System</p>
        </footer>
    </div>
</body>
</html>
